/**
 * A record of one completed x402 payment. Amounts are atomic units of `asset`
 * as decimal strings (bigint-safe in JSON).
 */
export type PaymentReceipt = {
    /** Account that paid. */
    account: string;
    url: string;
    network: string;
    asset: string;
    amount: string;
    scheme: string;
    /** Settlement tx hash, when the server returned one. */
    txHash?: string;
    /**
     * The public half of the signed EIP-3009 authorization: enough to ask the
     * token later whether this nonce was ever used (`buy receipts --resolve`,
     * #182). Never the signature, which is what would let anyone spend it.
     */
    authorization?: {
        from: string;
        nonce: string;
        validAfter: string;
        validBefore: string;
    };
    /**
     * Where to check on what was bought, when the paid response named a
     * same-origin URL (its Content-Location): for a VM, the free poll route with
     * instance, IP and status. Kept because a streamed body can scroll away (#85).
     */
    poll?: string;
    /** ISO-8601 time the paid response was received. */
    timestamp: string;
    /** HTTP status of the paid response, when the caller recorded one. */
    status?: number;
    /** confirmed | rejected | ambiguous — see OnPaymentInfo in @celo/buy-core. */
    outcome?: string;
    /**
     * Stable per-append identity. Set by `appendReceipt` and used to make the
     * append idempotent: the compare-and-swap may re-run the mutation against
     * state that already contains it, and without an id that would duplicate
     * the receipt.
     */
    id?: string;
};
/** Receipts are kept bounded: only the latest N survive each append. */
export declare const MAX_RECEIPTS = 500;
/**
 * Append a receipt to `$BUY_HOME/receipts.json` (plain JSON array, mode
 * 0600, oldest first), dropping the oldest entries past MAX_RECEIPTS.
 *
 * This is HISTORY, not accounting: it is bounded, so it forgets. The daily
 * cap is enforced against the unbounded ledger in spend-ledger.ts. The two
 * were once the same file, which meant a busy day silently shrank the total
 * the cap was measured against.
 *
 * Published through the same compare-and-swap as the ledger, because a plain
 * read-modify-write is lost-update-prone: two concurrent payments each read
 * the same array and the second write erases the first one's receipt.
 *
 * KNOWN LIMITATION — celo-org/cpay#19. The idempotency check below scans the
 * STORED list for its own id, and that list is truncated to MAX_RECEIPTS, so
 * the guarantee only holds while the entry survives truncation. If a retrying
 * writer is overtaken by 500+ appends, its retry no longer finds itself and
 * appends a duplicate carrying an older timestamp. History only: the spend
 * ledger is separate and unbounded, so the daily cap does not depend on any
 * receipt surviving. Raising MAX_RECEIPTS narrows that window without closing
 * it — the fix is to keep the dedupe set out of the truncated structure.
 */
export declare function appendReceipt(receipt: PaymentReceipt): Promise<void>;
/** All stored receipts, oldest first. Missing file reads as empty. */
export declare function readReceipts(): Promise<PaymentReceipt[]>;
